#!/usr/bin/env python3
"""GAP1 analysis (planned/GAP1_PREREG.md). References: INTENT2 (M1 at N2 = V14, N1; M1 risk), LAYOUT1 (M1 cut), CURVE1 (S1). Risk formula as INTENT2."""
import json, glob, math
rd = lambda p: [json.loads(l) for f in glob.glob(p) for l in open(f) if l.strip()]
NEW = rd('out/gap1/*.jsonl'); I2 = rd('out/intent2/*.jsonl')
C = [r for r in NEW if r['part'] == 'c'] + [dict(r, vol='V14') for r in I2 if r['part'] == 'c' and r['heights'] == 'M1' and r['vol'] == 'N2'] + [r for r in I2 if r['part'] == 'c' and r['heights'] == 'M1' and r['vol'] == 'N1']
R = [r for r in NEW if r['part'] == 'r'] + [r for r in I2 if r['part'] == 'r']
U = [r for r in NEW if r['part'] == 'u'] + [r for r in rd('out/layout1/*.jsonl') if r['part'] == 'u' and r['arm'] == 'M1' and r['seed'] <= 5] + [r for r in rd('out/curve1/*.jsonl') if r['arm'] == 'S1' and r['seed'] <= 5]
M, VT, SZ = ('houston', 'dfw'), [5, 7.5, 10, 12.5, 15, 20], ['V14', 'V135', 'V125', 'V115', 'V10', 'N1']
LV = {'L1': (3, 4), 'L2': (8, 13)}; K_RAD = math.sqrt(-2 * math.log(0.05)); K_VER = 1.96; WING = (0.65, 0.25); BIG = (1.5, 0.3)
Phi = lambda x: 0.5 * (1 + math.erf(x / math.sqrt(2)))
def band(d, W, s): return Phi((W - d) / s) - Phi((-W - d) / s) if s > 0 else (1.0 if abs(d) < W else 0.0)
size = lambda op: WING if op == 'wing' else BIG
def expected(row, lv):
    h95, v95 = LV[lv]; sh = math.sqrt(2) * h95 / K_RAD; sz = math.sqrt(2) * v95 / K_VER; p = 0.0
    for opA, opB, dperp, dz, dh, vrel in row['enc']: A, B = size(opA), size(opB); p += band(dperp, A[0] + B[0], sh) * band(dz, A[1] + B[1], sz)
    return p
LVL = {'N1': 'L1', 'N2': 'L2', 'NONE': 'L2'}
def rate(m, a, c):
    x = [r for r in R if r['metro'] == m and r['arm'] == a and r['check'] == c]; return 1e5 * sum(expected(r, LVL[c]) for r in x) / sum(r['flightHours'] for r in x) if x else float('nan')
def held(m, h, v, op='all'):
    x = [r for r in C if r['metro'] == m and r['heights'] == h and r['vol'] == v and op in r['cost']]; n = sum(r['cost'][op]['n'] for r in x)
    return sum(r['cost'][op]['delayed'] + r['cost'][op]['cancelled'] for r in x) / n if n else float('nan')
def ut(m, a, v): return sum(r['counts'][f'h30v{v:g}'] for r in U if r['metro'] == m and r['arm'] == a)
def cut(m, a, v): return 1 - ut(m, a, v) / ut(m, 'S1', v)
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
pc = lambda x: f'{100 * x:.1f} %'
chk('G1', all(abs(held(m, 'G1', 'V14', 'amazon') - held(m, 'M1', 'V14', 'amazon')) <= 0.10 for m in M), '; '.join(f'{m} Amazon V14 G1 {pc(held(m, "G1", "V14", "amazon"))} vs M1 {pc(held(m, "M1", "V14", "amazon"))}' for m in M))
chk('G2', all(held(m, 'G1', 'V135', 'amazon') < 0.5 * held(m, 'G1', 'V14', 'amazon') for m in M), '; '.join(f'{m} G1 Amazon V135 {pc(held(m, "G1", "V135", "amazon"))} vs V14 {pc(held(m, "G1", "V14", "amazon"))}' for m in M))
chk('G3', all(abs(held(m, 'M1', 'V135', 'amazon') - held(m, 'M1', 'V14', 'amazon')) <= 0.10 and held(m, 'M1', 'V115', 'amazon') < 0.5 * held(m, 'M1', 'V14', 'amazon') for m in M), '; '.join(f'{m} M1 Amazon V14 {pc(held(m, "M1", "V14", "amazon"))}, V135 {pc(held(m, "M1", "V135", "amazon"))}, V115 {pc(held(m, "M1", "V115", "amazon"))}' for m in M))
chk('G4', all(held(m, 'G1', 'V135') < 0.5 * held(m, 'M1', 'V135') for m in M), '; '.join(f'{m} all V135 G1 {pc(held(m, "G1", "V135"))} vs M1 {pc(held(m, "M1", "V135"))}' for m in M))
chk('G5', all(held(m, 'G1', 'V135', 'amazon') >= 0.20 for m in M), '; '.join(f'{m} G1 Amazon V135 {pc(held(m, "G1", "V135", "amazon"))}' for m in M))
chk('G6', all(rate(m, 'G1', 'N2') < rate(m, 'M1', 'N2') for m in M), '; '.join(f'{m} N2 G1 {rate(m, "G1", "N2"):.3g} vs M1 {rate(m, "M1", "N2"):.3g}' for m in M))
chk('G7', all(cut(m, 'G1', 10) >= 0.80 for m in M), '; '.join(f'{m} G1 cut {100 * cut(m, "G1", 10):.0f} %' for m in M))
npass = sum(1 for _, ok, _ in P if ok)
L = ['# GAP1 results table (generated by planned/gap1_analyze.py)', '', f'{npass} of {len(P)} predictions passed. New rows: {len(NEW)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## Held share by plan height allowance (windy hours, seeds 1-5)', '', '| Metro | Layout | Plan | All | Wing | Zipline | Amazon |', '|---|---|---|---|---|---|---|']
for m in M:
    for h in ('G1', 'M1'):
        for v in SZ: L.append(f'| {m} | {h} | {v} | {pc(held(m, h, v))} | {pc(held(m, h, v, "wing"))} | {pc(held(m, h, v, "zipline"))} | {pc(held(m, h, v, "amazon"))} |')
L += ['', '## Residual collision risk per 100,000 flight hours (still air)', '', '| Metro | Layout | No check (L2) | N1 (L1) | N2 (L2) |', '|---|---|---|---|---|']
for m in M:
    for a in ('A2', 'M1', 'G1'): L.append(f'| {m} | {a} | {rate(m, a, "NONE"):.3g} | {rate(m, a, "N1"):.3g} | {rate(m, a, "N2"):.3g} |')
L += ['', '## Cut against S1 without plan sharing (30 m sideways; seeds 1-5)', '', '| Metro | Layout | ' + ' | '.join(f'{v:g} m' for v in VT) + ' |', '|---|---|' + '---|' * len(VT)]
for m in M:
    for a in ('M1', 'G1'): L.append(f'| {m} | {a} | ' + ' | '.join(f'{100 * cut(m, a, v):.0f} %' for v in VT) + ' |')
open('planned/gap1_results_table.md', 'w').write('\n'.join(L) + '\n'); print(f'{npass} of {len(P)} passed')
